/*
  تحميل ملفات الصفحات مسبقًا بعد استقرار الصفحة الأولى.
  هذا لا يغيّر الواجهات أو الأنيميشن، لكنه يجعل أول دخول لكل صفحة أسرع.
*/
if (typeof window !== "undefined") {
  const prefetchRoutes = () => {
    void import("./pages/HomePage.js");
    void import("./components/TibyanSettings.js");
    void import("./pages/PharmacyPage.js");
    void import("./pages/NutritionPage.js");
    void import("./pages/LabsPage.js");
    void import("./pages/ConsultationsPage.js");
    void import("./pages/PlaceholderPage.js");
    void import("./doctor/DoctorLayout.js");
    void import("./pages/doctor/DoctorDashboard.js");
    void import("./pharmacy/PharmacyLayout.js");
    void import("./pages/pharmacy/PharmacyDashboard.js");
  };

  if ("requestIdleCallback" in window) {
    window.requestIdleCallback(prefetchRoutes, { timeout: 900 });
  } else {
    window.setTimeout(prefetchRoutes, 350);
  }
}

/* =========================================================
   حركة الانتقال الأصلية المستخرجة من الصفحة المرجعية
   الشعار ثابت في الوسط والأيقونات تظهر بالتسلسل
========================================================= */

const TABYAN_EXACT_LOGO =
  "data:image/png;base64,";

const TabyanTransitionLogo = memo(function TabyanTransitionLogo({
  className = "",
  decorative = false,
}) {
  return (
    <img
      src={TABYAN_EXACT_LOGO}
      alt={decorative ? "" : "شعار تبيان"}
      aria-hidden={decorative}
      draggable={false}
      decoding="async"
      fetchPriority="high"
      className={className}
    />
  );
});

/*
  تجهيز الشعار في وقت خمول المتصفح حتى تكون حركة الانتقال الأصلية
  جاهزة وسلسة عند أول تنقل، من دون تغيير الرسم أو الحركة.
*/
if (typeof window !== "undefined") {
  const prepareTransitionLogo = () => {
    const image = new Image();
    image.src = TABYAN_EXACT_LOGO;
    if (typeof image.decode === "function") {
      image.decode().catch(() => undefined);
    }
  };

  if ("requestIdleCallback" in window) {
    window.requestIdleCallback(prepareTransitionLogo, { timeout: 1200 });
  } else {
    window.setTimeout(prepareTransitionLogo, 0);
  }
}

function RouteTransition() {
  const location = useLocation();
  const firstRender = useRef(true);
  const closingTimerRef = useRef(null);
  const finishTimerRef = useRef(null);
  const frameRef = useRef(null);
  const [showIntro, setShowIntro] = useState(false);
  const [introClosing, setIntroClosing] = useState(false);

  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return undefined;
    }

    if (closingTimerRef.current) window.clearTimeout(closingTimerRef.current);
    if (finishTimerRef.current) window.clearTimeout(finishTimerRef.current);

    if (frameRef.current) window.cancelAnimationFrame(frameRef.current);

    /*
      نبدأ شاشة الانتقال في إطار رسم مستقل. هذا يمنع تجميد النقر
      مع إبقاء مدة وتسلسل الأنيميشن الأصليين كما هما.
    */
    frameRef.current = window.requestAnimationFrame(() => {
      setIntroClosing(false);
      setShowIntro(true);
    });

    closingTimerRef.current = window.setTimeout(() => {
      setIntroClosing(true);
    }, 720);

    finishTimerRef.current = window.setTimeout(() => {
      setShowIntro(false);
      setIntroClosing(false);
    }, 860);

    return () => {
      if (frameRef.current) window.cancelAnimationFrame(frameRef.current);
      if (closingTimerRef.current) window.clearTimeout(closingTimerRef.current);
      if (finishTimerRef.current) window.clearTimeout(finishTimerRef.current);
    };
  }, [location.pathname]);

  if (!showIntro) return null;

  return (
    <section
      key={location.pathname}
      className={`tabyan-intro-screen ${introClosing ? "tabyan-intro-closing" : ""}`}
      role="status"
      aria-label="جاري فتح الصفحة"
      aria-busy="true"
    >
      <div className="tabyan-sequence-loader" aria-hidden="true">
        <span className="tabyan-sequence-halo" />
        <span className="tabyan-route-orbit" />
        <span className="tabyan-route-particle" />

        <div className="tabyan-logo-fixed">
          <TabyanTransitionLogo decorative className="tabyan-logo-image" />
        </div>

        <span className="tabyan-icon-cover tabyan-cover-stethoscope" />
        <span className="tabyan-icon-cover tabyan-cover-report" />
        <span className="tabyan-icon-cover tabyan-cover-lab" />
        <span className="tabyan-icon-cover tabyan-cover-pill" />
        <span className="tabyan-icon-cover tabyan-cover-calendar" />
        <span className="tabyan-icon-cover tabyan-cover-nutrition" />

        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-stethoscope" />
        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-report" />
        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-lab" />
        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-pill" />
        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-calendar" />
        <TabyanTransitionLogo decorative className="tabyan-icon-slice tabyan-icon-nutrition" />

        <span className="tabyan-final-ring" />
      </div>
    </section>
  );
}

